{
  "task": "format_questions_to_latex",
  "questions": [
    {
      "source_id": "1",
      "stem": "A research rover is located at the origin of an \\(xy\\)-plane. A sensor beacon is at position \\(\\vec r = -9\\hat{i} + 12\\hat{j}\\), where distances are measured in kilometers. Which statement is correct?",
      "options": [
        {
          "key": "A",
          "text": "The beacon is 21 km from the rover.",
          "is_correct": false,
          "explanation": "This adds the magnitudes of the components, \\(9+12\\), instead of calculating the magnitude of the vector. Distance from the origin must be found using \\(|\\vec r|=\\sqrt{x^2+y^2}\\), not by simple addition."
        },
        {
          "key": "B",
          "text": "The beacon is 12 km from the rover.",
          "is_correct": false,
          "explanation": "This uses only the \\(y\\)-component as the full distance. In two dimensions, both the \\(x\\)- and \\(y\\)-components contribute to the magnitude."
        },
        {
          "key": "C",
          "text": "The beacon is 15 km from the rover.",
          "is_correct": true,
          "explanation": "The distance from the origin is the magnitude of the position vector. Using \\(|\\vec r|=\\sqrt{(-9)^2+12^2}=\\sqrt{81+144}=\\sqrt{225}=15\\,\\text{km}\\), the beacon is 15 km away. This applies the Pythagorean theorem to the perpendicular vector components."
        },
        {
          "key": "D",
          "text": "The beacon is 9 km from the rover.",
          "is_correct": false,
          "explanation": "This uses only the \\(x\\)-component's magnitude as the total distance. A single component is not the same as the full vector magnitude unless the other component is zero."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    },
    {
      "source_id": "2",
      "stem": "The position of a cart moving along the \\(x\\)-axis is given by \\(\\vec s(t)=\\big[(2.4\\,\\text{m/s}^3)t^3-(1.1\\,\\text{m/s}^2)t^2\\big]\\hat{i}\\). Which statement is correct?",
      "options": [
        {
          "key": "A",
          "text": "This motion has constant acceleration.",
          "is_correct": false,
          "explanation": "A cubic position function does not lead to constant acceleration. Taking two derivatives gives an acceleration that still depends on \\(t\\)."
        },
        {
          "key": "B",
          "text": "The magnitude of the acceleration at \\(t=0\\) is \\(2.2\\,\\text{m/s}^2\\).",
          "is_correct": true,
          "explanation": "Differentiate the position twice: \\(v(t)=\\frac{ds}{dt}=7.2t^2-2.2t\\) and \\(a(t)=\\frac{dv}{dt}=14.4t-2.2\\). At \\(t=0\\), the acceleration is \\(a(0)=-2.2\\,\\text{m/s}^2\\), so its magnitude is \\(2.2\\,\\text{m/s}^2\\). The correct statement focuses on the magnitude, not the sign."
        },
        {
          "key": "C",
          "text": "The acceleration is always \\(1.1\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "This incorrectly treats the coefficient of the \\(t^2\\) term in position as the acceleration itself. Acceleration comes from the second derivative of position, not directly from a coefficient in \\(s(t)\\)."
        },
        {
          "key": "D",
          "text": "The magnitude of the acceleration at \\(t=0\\) is \\(0\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "This mistake comes from assuming every term vanishes at \\(t=0\\) after differentiation. The second derivative leaves the constant term \\(-2.2\\,\\text{m/s}^2\\), so the magnitude is not zero."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    },
    {
      "source_id": "3",
      "stem": "A particle takes 4.0 s to move from position \\(\\vec r_A = 3\\hat{i}-2\\hat{j}\\) m to position \\(\\vec r_B = -9\\hat{i}+7\\hat{j}\\) m. Which statement is correct?",
      "options": [
        {
          "key": "A",
          "text": "The distance traveled by the particle is 15 m.",
          "is_correct": false,
          "explanation": "The value 15 m is the magnitude of the displacement, not necessarily the actual path length. Distance traveled depends on the path taken, which is not specified."
        },
        {
          "key": "B",
          "text": "The speed at \\(t=0\\) must be \\(3.75\\,\\text{m/s}\\).",
          "is_correct": false,
          "explanation": "This divides displacement magnitude by elapsed time to get an average rate and then incorrectly treats it as the initial speed. Instantaneous speed at \\(t=0\\) cannot be determined from only the starting point, ending point, and total time."
        },
        {
          "key": "C",
          "text": "The acceleration at \\(t=0\\) must be \\(0.94\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "Acceleration requires more detailed information about how velocity changes with time. Initial and final position plus total time are not enough to determine the acceleration at a specific instant."
        },
        {
          "key": "D",
          "text": "None of the above is correct.",
          "is_correct": true,
          "explanation": "From the given data, the displacement is \\(\\Delta \\vec r=\\vec r_B-\\vec r_A=(-12\\hat{i}+9\\hat{j})\\,\\text{m}\\), whose magnitude is \\(|\\Delta \\vec r|=\\sqrt{(-12)^2+9^2}=15\\,\\text{m}\\). However, that value is not guaranteed to equal the distance traveled, and the initial speed and initial acceleration cannot be inferred from the limited information provided. Therefore A, B, and C are all false."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    }
  ],
  "requirements": {
    "include_document_preamble": true,
    "include_macros": [
      "\\QBlock",
      "\\Correct",
      "\\Wrong",
      "\\OEBlock",
